void lc_factory_check(const LcCapture* capture, LcFactory* out) {
    if(!out) return;
    memset(out, 0, sizeof(*out));
    if(!lc_capture_complete(capture)) return;
    uint8_t plain[LC_FRAM_SIZE];
    lc_integrity_transform(capture->uid, capture->patch, capture->fram, plain);
    lc_factory_parse(plain, capture->patch, out);
    volatile uint8_t* wipe = plain;
    for(size_t i = 0; i < sizeof(plain); i++) wipe[i] = 0;
}

void lc_factory_parse(const uint8_t plain[344], const uint8_t patch[6], LcFactory* out) {
    if(!out) return;
    memset(out, 0, sizeof(*out));
    out->status = LcFactoryRejected;
    LcSensor s;
    lc_sensor_parse(plain, patch, &s);
    if(s.parse_status != LcSensorParsed || s.status_code != 3 || !s.max_life_minutes ||
       s.age_minutes > s.max_life_minutes || s.has_error || s.quality_bits || s.quality_flags) return;
    uint64_t footer = 0, word = 0;
    for(unsigned i = 0; i < 8; i++) footer |= (uint64_t)plain[336+i] << (8*i);
    for(unsigned i = 0; i < 6; i++) word |= (uint64_t)plain[28+s.newest_slot*6+i] << (8*i);
    LcFactoryCoefficients c = {
        .i1 = plain[2]&7, .i2 = ((plain[2] | ((unsigned)plain[3]<<8))>>3)&1023,
        .i3 = (int)(footer&255)*((footer>>33)&1 ? -1 : 1),
        .i4 = (footer>>8)&16383, .i5 = ((footer>>40)&4095)<<2,
        .i6 = ((footer>>52)&4095)<<2,
    };
    LcFactoryRecord r = {
        .raw_adc = word&16383, .raw_temperature = ((word>>26)&4095)<<2,
        .temperature_adjustment = (int)(((word>>38)&511)<<2)*((word>>47)&1 ? -1 : 1),
        .sensor_minute = s.age_minutes, .quality_bits = s.quality_bits,
        .quality_flags = s.quality_flags, .has_error = s.has_error,
    };
    lc_factory_calculate(&r, &c, out);
}

void lc_factory_calculate(const LcFactoryRecord* r, const LcFactoryCoefficients* c, LcFactory* out) {
    if(!out) return;
    memset(out, 0, sizeof(*out));
    if(!r || !c) return;
    out->status = LcFactoryRejected;
    if(c->i1 < 0 || c->i1 > 7 || c->i2 < 1 || c->i2 > 1023 ||
       c->i3 < -255 || c->i3 > 255 || c->i4 < 0 || c->i4 > 16383 ||
       c->i5 < 0 || c->i5 > 16380 || c->i6 < 1 || c->i6 > 16380 ||
       r->raw_adc < 1 || r->raw_adc > 16383 || r->raw_temperature < 1 ||
       r->raw_temperature > 16380 || r->temperature_adjustment < -2044 ||
       r->temperature_adjustment > 2044 || r->sensor_minute < 0 ||
       r->sensor_minute > 65535 || r->has_error || r->quality_bits || r->quality_flags ||
       c->i4 <= c->i3 || r->temperature_adjustment + c->i6 <= 0) return;
    double resistance = r->raw_temperature * D(72500.0) / (r->temperature_adjustment + c->i6) - D(1000.0);
    if(!isfinite(resistance) || resistance <= D(0.0)) return;
    double log_r = log(resistance);
    double temperature = D(1.0) / (pow(log_r, D(3.0)) * D(0.00000005283566) +
        pow(log_r, D(2.0)) * D(0.0000007061775) + log_r * D(0.0001964561) + D(0.0009180023)) - D(273.15);
    double g1 = D(65.0) * (r->raw_adc - c->i3) / (c->i4 - c->i3);
    double g2 = pow(D(1.045), D(32.5) - temperature);
    double value = (g1 * g2 - t1[c->i2-1]) / t2[c->i2-1];
    /* Rendering/representation bound, NOT a physiological plausibility gate. */
    if(!isfinite(temperature) || !isfinite(value) || value <= D(0.0) || value > D(9999.0)) return;
    out->temperature_c = temperature;
    out->unrounded_mg_dl = value;
    out->mg_dl = (uint32_t)floor(value+D(0.5));
    out->mmol_tenths = (uint32_t)floor(out->mg_dl / D(18.0) * D(10.0) + D(0.5));
    out->status = LcFactoryEstimate;
}
